/**
 * Tool logos for the homepage Toolbox, as inline SVG (fill: currentColor).
 *
 * Brand marks from Simple Icons 13.21.0 (CC0) and Devicon 2.16.0 (MIT, VS Code).
 * Liquid and Cursor have no free logo in either set, so they get simple drawn marks.
 * Logos belong to their owners and are shown only to name the tools Elisa uses.
 *
 * @package elisa-dela-cruz
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Icon key for a tool name typed in ACF (Toolbox), or '' when there's no logo.
 */
function edc_tool_icon_key( $name ) {
	$n = strtolower( preg_replace( '/[^a-z0-9]+/i', '', (string) $name ) );
	$map = array(
		'wordpress' => 'wordpress',
		'woocommerce' => 'wordpress',
		'shopify' => 'shopify',
		'shopifyplus' => 'shopify',
		'liquid' => 'liquid',
		'shopifyliquid' => 'liquid',
		'html' => 'html5',
		'html5' => 'html5',
		'css' => 'css3',
		'css3' => 'css3',
		'jquery' => 'jquery',
		'tailwind' => 'tailwind',
		'tailwindcss' => 'tailwind',
		'adobe' => 'adobe',
		'adobecc' => 'adobe',
		'adobecreativecloud' => 'adobe',
		'vscode' => 'vscode',
		'visualstudiocode' => 'vscode',
		'github' => 'github',
		'cursor' => 'cursor',
		'claude' => 'claude',
		'claudecode' => 'claude',
		'vercel' => 'vercel',
		'supabase' => 'supabase',
	);
	return isset( $map[ $n ] ) ? $map[ $n ] : '';
}

